Problem:
A doctor can prescribe two types of medication for high glucose levels, a diabetic pill and a diabetic shot. Per dose, diabetic pill delivers 1 unit of glucose reducing medicine and 2 units of blood pressure reducing medicine. Per dose, a diabetic shot delivers 2 units of glucose reducing medicine and 3 units of blood pressure reducing medicine. In addition, diabetic pills provide 0.4 units of stress and the diabetic shot provides 0.9 units of stress. At most 20 units of stress can be applied over a week and the doctor must deliver at least 30 units of glucose reducing medicine. How many doses of each should be delivered to maximize the amount of blood pressure reducing medicine delivaered to the patient?

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "diabetic pill doses",
    "lower": 0.0,
    "upper": null,
    "integer": true
   },
   {
    "name": "diabetic shot doses",
    "lower": 0.0,
    "upper": null,
    "integer": true
   }
  ],
  "objective": {
   "sense": "max",
   "terms": [
    {
     "var": "diabetic pill doses",
     "coef": 2.0
    },
    {
     "var": "diabetic shot doses",
     "coef": 3.0
    }
   ]
  },
  "constraints": [
   {
    "name": "stress",
    "terms": [
     {
      "var": "diabetic pill doses",
      "coef": 0.4
     },
     {
      "var": "diabetic shot doses",
      "coef": 0.9
     }
    ],
    "sense": "<=",
    "rhs": 20.0
   },
   {
    "name": "glucose",
    "terms": [
     {
      "var": "diabetic pill doses",
      "coef": 1.0
     },
     {
      "var": "diabetic shot doses",
      "coef": 2.0
     }
    ],
    "sense": ">=",
    "rhs": 30.0
   }
  ]
 },
 "facts": {
  "objective": 100.0,
  "values": {
   "diabetic pill doses": 50.0,
   "diabetic shot doses": 0.0
  },
  "binding": [
   "stress"
  ],
  "slack": {
   "stress": 0.0,
   "glucose": 20.0
  },
  "shadow_prices": null,
  "limits": {
   "stress": {
    "dropped_improves": true,
    "loosened_improves": true
   },
   "glucose": {
    "dropped_improves": false,
    "loosened_improves": false
   }
  }
 }
}
